effect.shader:
float amostraCanal(vec2 uv, vec2 c, float esc, int canal, int n) {
    float soma = 0.0;
    for (int i = 0; i <= 48; i++) {
        if (i > n) break;
        float t = float(i) / float(n);
        vec2 p = mix(uv, c, t * esc);
        soma += texture(inputImg, p)[canal];
    }
    return soma / float(n + 1);
}

void main() {
    vec4 original = texture(inputImg, acScreenNorm);
    if (strength <= 0.0) { fragColor = original; return; }

    int n = clamp(int(samples), 4, 48);
    float escR = strength * (1.0 + chroma);
    float escG = strength;
    float escB = strength * (1.0 - chroma);

    float r = amostraCanal(acScreenNorm, center, escR, 0, n);
    float g = amostraCanal(acScreenNorm, center, escG, 1, n);
    float b = amostraCanal(acScreenNorm, center, escB, 2, n);

    fragColor = vec4(r, g, b, original.a);
}
